ALTER TABLE communication_registry MODIFY COLUMN operacion_id VARCHAR(36) NULL;
CREATE TABLE core_unit(code VARCHAR(8) PRIMARY KEY,label VARCHAR(120) NOT NULL) ENGINE=InnoDB;
CREATE TABLE core_site(id VARCHAR(40) PRIMARY KEY,label VARCHAR(120) NOT NULL) ENGINE=InnoDB;
CREATE TABLE core_unit_site(unit_code VARCHAR(8) NOT NULL,site_id VARCHAR(40) NOT NULL,PRIMARY KEY(unit_code,site_id),FOREIGN KEY(unit_code) REFERENCES core_unit(code),FOREIGN KEY(site_id) REFERENCES core_site(id)) ENGINE=InnoDB;
CREATE TABLE core_actor(id VARCHAR(64) PRIMARY KEY,label VARCHAR(120) NOT NULL,role_code VARCHAR(20) NOT NULL,unit_code VARCHAR(8),site_id VARCHAR(40),FOREIGN KEY(unit_code,site_id) REFERENCES core_unit_site(unit_code,site_id),CHECK(role_code IN ('DISTRIBUCION','JEFATURA','PROFESIONAL'))) ENGINE=InnoDB;
CREATE TABLE core_communication(id VARCHAR(36) PRIMARY KEY,state VARCHAR(24) NOT NULL,revision BIGINT NOT NULL,site_id VARCHAR(40),decision_text TEXT,decided_by VARCHAR(64),decided_ms BIGINT,FOREIGN KEY(id) REFERENCES communication_registry(comunicacion_id),FOREIGN KEY(site_id) REFERENCES core_site(id),FOREIGN KEY(decided_by) REFERENCES core_actor(id),CHECK(state IN ('ABIERTA','RESPONDIDA','DESCARTADA'))) ENGINE=InnoDB;
CREATE TABLE core_manual(communication_id VARCHAR(36) PRIMARY KEY,received_declared_ms BIGINT NOT NULL,channel_declared VARCHAR(100) NOT NULL,body_text TEXT NOT NULL,actor_id VARCHAR(64) NOT NULL,FOREIGN KEY(communication_id) REFERENCES core_communication(id),FOREIGN KEY(actor_id) REFERENCES core_actor(id)) ENGINE=InnoDB;
CREATE TABLE core_destination(id VARCHAR(36) PRIMARY KEY,communication_id VARCHAR(36) NOT NULL,unit_code VARCHAR(8) NOT NULL,site_id VARCHAR(40) NOT NULL,evaluator_id VARCHAR(64) NOT NULL,state VARCHAR(20) NOT NULL,revision BIGINT NOT NULL,created_ms BIGINT NOT NULL,created_by VARCHAR(64) NOT NULL,decision VARCHAR(40),decision_text TEXT,decided_by VARCHAR(64),decided_ms BIGINT,UNIQUE(id,communication_id),FOREIGN KEY(communication_id) REFERENCES core_communication(id),FOREIGN KEY(unit_code,site_id) REFERENCES core_unit_site(unit_code,site_id),FOREIGN KEY(evaluator_id) REFERENCES core_actor(id),FOREIGN KEY(created_by) REFERENCES core_actor(id),FOREIGN KEY(decided_by) REFERENCES core_actor(id),CHECK(state IN ('EVALUANDO','RESUELTO'))) ENGINE=InnoDB;
CREATE INDEX ix_core_destination_scope ON core_destination(unit_code,site_id,communication_id);
CREATE TABLE core_requirement(id VARCHAR(36) PRIMARY KEY,communication_id VARCHAR(36) NOT NULL UNIQUE,state VARCHAR(16) NOT NULL,revision BIGINT NOT NULL,created_ms BIGINT NOT NULL,created_by VARCHAR(64) NOT NULL,ended_ms BIGINT,UNIQUE(id,communication_id),FOREIGN KEY(communication_id) REFERENCES core_communication(id),FOREIGN KEY(created_by) REFERENCES core_actor(id),CHECK(state IN ('ACTIVO','TERMINADO'))) ENGINE=InnoDB;
CREATE TABLE core_case(id VARCHAR(36) PRIMARY KEY,communication_id VARCHAR(36) NOT NULL,requirement_id VARCHAR(36) NOT NULL,destination_id VARCHAR(36) NOT NULL,responsible_id VARCHAR(64) NOT NULL,complexity_text VARCHAR(300),state VARCHAR(24) NOT NULL,revision BIGINT NOT NULL,created_ms BIGINT NOT NULL,created_by VARCHAR(64) NOT NULL,closed_ms BIGINT,closed_by VARCHAR(64),origin_case_id VARCHAR(36),FOREIGN KEY(requirement_id,communication_id) REFERENCES core_requirement(id,communication_id),FOREIGN KEY(destination_id,communication_id) REFERENCES core_destination(id,communication_id),FOREIGN KEY(responsible_id) REFERENCES core_actor(id),FOREIGN KEY(created_by) REFERENCES core_actor(id),FOREIGN KEY(closed_by) REFERENCES core_actor(id),FOREIGN KEY(origin_case_id) REFERENCES core_case(id),CHECK(state IN ('EN_GESTION','REVISION_TERMINO','CERRADO'))) ENGINE=InnoDB;
CREATE INDEX ix_core_case_responsible ON core_case(responsible_id,communication_id);
CREATE TABLE core_assignment(id VARCHAR(36) PRIMARY KEY,case_id VARCHAR(36) NOT NULL,responsible_id VARCHAR(64) NOT NULL,complexity_text VARCHAR(300),actor_id VARCHAR(64) NOT NULL,at_ms BIGINT NOT NULL,FOREIGN KEY(case_id) REFERENCES core_case(id),FOREIGN KEY(responsible_id) REFERENCES core_actor(id),FOREIGN KEY(actor_id) REFERENCES core_actor(id)) ENGINE=InnoDB;
CREATE TABLE core_action(id VARCHAR(36) PRIMARY KEY,case_id VARCHAR(36) NOT NULL,actor_id VARCHAR(64) NOT NULL,at_ms BIGINT NOT NULL,body_text TEXT NOT NULL,FOREIGN KEY(case_id) REFERENCES core_case(id),FOREIGN KEY(actor_id) REFERENCES core_actor(id)) ENGINE=InnoDB;
CREATE TABLE core_review(id VARCHAR(36) PRIMARY KEY,case_id VARCHAR(36) NOT NULL,actor_id VARCHAR(64) NOT NULL,at_ms BIGINT NOT NULL,decision VARCHAR(32) NOT NULL,body_text TEXT NOT NULL,FOREIGN KEY(case_id) REFERENCES core_case(id),FOREIGN KEY(actor_id) REFERENCES core_actor(id),CHECK(decision IN ('SOLICITUD_TERMINO','DEVOLUCION','CIERRE'))) ENGINE=InnoDB;
CREATE TABLE core_link(child_id VARCHAR(36) PRIMARY KEY,parent_id VARCHAR(36) NOT NULL,case_reference VARCHAR(36),actor_id VARCHAR(64) NOT NULL,at_ms BIGINT NOT NULL,reason_text VARCHAR(1000) NOT NULL,FOREIGN KEY(child_id) REFERENCES core_communication(id),FOREIGN KEY(parent_id) REFERENCES core_communication(id),FOREIGN KEY(case_reference) REFERENCES core_case(id),FOREIGN KEY(actor_id) REFERENCES core_actor(id),CHECK(child_id<>parent_id)) ENGINE=InnoDB;
CREATE TABLE core_notice(id VARCHAR(36) PRIMARY KEY,child_id VARCHAR(36) NOT NULL,parent_id VARCHAR(36) NOT NULL,recipient_id VARCHAR(64),at_ms BIGINT NOT NULL,read_ms BIGINT,FOREIGN KEY(child_id) REFERENCES core_communication(id),FOREIGN KEY(parent_id) REFERENCES core_communication(id),FOREIGN KEY(recipient_id) REFERENCES core_actor(id)) ENGINE=InnoDB;
CREATE INDEX ix_core_notice_recipient ON core_notice(recipient_id,read_ms);
CREATE TABLE core_event(seq BIGINT AUTO_INCREMENT PRIMARY KEY,communication_id VARCHAR(36) NOT NULL,resource_kind VARCHAR(24) NOT NULL,resource_id VARCHAR(36) NOT NULL,actor_id VARCHAR(64) NOT NULL,at_ms BIGINT NOT NULL,code VARCHAR(64) NOT NULL,FOREIGN KEY(communication_id) REFERENCES core_communication(id),FOREIGN KEY(actor_id) REFERENCES core_actor(id)) ENGINE=InnoDB;
CREATE INDEX ix_core_history ON core_event(communication_id,seq);
CREATE TABLE core_command(id VARCHAR(36) PRIMARY KEY,actor_id VARCHAR(64) NOT NULL,action_code VARCHAR(40) NOT NULL,request_hash CHAR(64) NOT NULL,result_id VARCHAR(36) NOT NULL,result_revision BIGINT NOT NULL,at_ms BIGINT NOT NULL,FOREIGN KEY(actor_id) REFERENCES core_actor(id)) ENGINE=InnoDB;

CREATE TABLE core_link_guard(id INT PRIMARY KEY) ENGINE=InnoDB;
INSERT INTO core_link_guard VALUES(1);
